// Player-created astronauts use original schematic parts, separate from the canonical cast.
export const jaccPaints={red:'#cf4348',green:'#38864a',pink:'#d76a9d',yellow:'#edc74d',white:'#f2f2e8',black:'#303842',orange:'#d96b24',purple:'#8653b6',blue:'#347ec5'};
export const jaccSkins={light:'#f0cfb3',warm:'#dfb184',tan:'#be8964',brown:'#986744',deep:'#704a35',dark:'#493325'};
export const jaccJobs={
 magnet:{name:'Magnet tool',icon:'🧲',target:'magnetism-poles'},optics:{name:'Light tool',icon:'🌈',target:'crystal'},geology:{name:'Sample scanner',icon:'💎',target:'grounds-dig'},engineering:{name:'Gripper / drill kit',icon:'🦾',target:'yard-free'},flight:{name:'Flight tools',icon:'🪽',target:'grounds-flight'},biology:{name:'Life lens',icon:'🧬',owner:'Lucas Turner',power:'bio-vision'},ecosystems:{name:'Eco probe',icon:'🌿',owner:'Sumati Suri',power:'connection-vision'},math:{name:'Math projector',icon:'🔷',owner:'Lilja Jónsdóttir',power:'pattern-vision'},space:{name:'Star finder',icon:'🔭',target:'rocketlab-sky'},none:{name:'Plain glove',icon:'✋'}
};
export const jaccSlots={helmet:{name:'Helmet',options:['round','bubble','wide']},armor:{name:'Armor',options:['explorer','panels','padded']},boots:{name:'Boots',options:['grip','moon','wade']},core:{name:'STEM core',options:Object.keys(jaccJobs).filter(k=>k!=='none')},back:{name:'Wings / thrusters',options:['wings','thrusters','both']},left:{name:'Left arm tool',options:Object.keys(jaccJobs)},right:{name:'Right arm tool',options:Object.keys(jaccJobs)}};
const jaccNames={round:'Round helmet',bubble:'Bubble helmet',wide:'Wide visor',explorer:'Explorer armor',panels:'Panel armor',padded:'Padded armor',grip:'Grip boots',moon:'Moon boots',wade:'Water boots',wings:'Wings',thrusters:'Twin thrusters',both:'Wings + thrusters'};
export function defaultJacc(){return {name:'My Astronaut',country:'',skin:'warm',face:'smile',parts:{helmet:'round',armor:'explorer',boots:'grip',core:'geology',back:'thrusters',left:'engineering',right:'biology'},colors:{helmet:'orange',armor:'blue',boots:'yellow',core:'blue',back:'white',left:'orange',right:'purple'},editId:null};}
const jaccClean=(v,n)=>typeof v==='string'?v.replace(/[\u0000-\u001f<>]/g,'').trim().slice(0,n):'';
export function normalizeJacc(raw={}){const d=defaultJacc(),r=raw&&typeof raw==='object'?raw:{};d.name=jaccClean(r.name,24)||d.name;d.country=jaccClean(r.country,40);if(Object.hasOwn(jaccSkins,r.skin))d.skin=r.skin;if(['smile','grin','freckles'].includes(r.face))d.face=r.face;for(const [slot,cfg]of Object.entries(jaccSlots)){if(cfg.options.includes(r.parts?.[slot]))d.parts[slot]=r.parts[slot];if(Object.hasOwn(jaccPaints,r.colors?.[slot]))d.colors[slot]=r.colors[slot];}d.editId=typeof r.editId==='string'&&/^c[1-8]$/.test(r.editId)?r.editId:null;return d;}
function jaccDraft(raw={}){const d=normalizeJacc(raw);for(const k of ['name','country'])if(typeof raw?.[k]==='string')d[k]=raw[k].replace(/[\u0000-\u001f<>]/g,'').slice(0,k==='name'?24:40);return d;}
export function normalizeJaccBuilder(raw={}){const r=raw&&typeof raw==='object'?raw:{},s={draft:jaccDraft(r.draft),models:[],activeId:null,history:[]};for(const m of Array.isArray(r.models)?r.models:[]){if(!m||!/^c[1-8]$/.test(m.id)||s.models.some(d=>d.id===m.id))continue;s.models.push({...normalizeJacc(m),id:m.id,editId:null});}if(s.models.some(m=>m.id===r.activeId))s.activeId=r.activeId;if(!s.models.some(m=>m.id===s.draft.editId))s.draft.editId=null;s.history=(Array.isArray(r.history)?r.history:[]).slice(-12).map(jaccDraft);return s;}
export function activeCustomJacc(s){return s?.models?.find(m=>m.id===s.activeId)||null;}
export function jaccMatchIndex(d,roster){return roster.findIndex(r=>r[1].toLowerCase()===normalizeJacc(d).colors.armor);}
export function customJaccTool(d,slot){return jaccJobs[d?.parts?.[slot]]||null;}
export function jaccBuilderAction(raw,a){const s=normalizeJaccBuilder(raw);let route=a.route||'home',message='',play=false;const remember=()=>{s.history.push(JSON.parse(JSON.stringify(s.draft)));s.history=s.history.slice(-12);};if(a.type==='part'&&jaccSlots[a.slot]?.options.includes(a.value)){remember();s.draft.parts[a.slot]=a.value;route='slot:'+a.slot;}if(a.type==='paint'&&jaccSlots[a.slot]&&Object.hasOwn(jaccPaints,a.value)){remember();s.draft.colors[a.slot]=a.value;route='slot:'+a.slot;}if(a.type==='identity'&&['name','country','skin','face'].includes(a.field)){remember();s.draft=jaccDraft({...s.draft,[a.field]:a.value});route=a.field==='name'?'name':a.field==='country'?'country':'identity';}if(a.type==='key'&&['name','country'].includes(a.field)){remember();const old=s.draft[a.field],limit=a.field==='name'?24:40;let value=a.value==='delete'?[...old].slice(0,-1).join(''):a.value==='clear'?'':old+(a.value==='space'?' ':/^[A-Z]$/.test(a.value)?a.value:'');s.draft[a.field]=value.slice(0,limit);route='keys:'+a.field+':'+(a.page||0);}if(a.type==='undo'){const d=s.history.pop();if(d)s.draft=d;route='home';}if(a.type==='new'){s.draft=defaultJacc();s.history=[];route='home';}if(a.type==='edit'){const m=s.models.find(m=>m.id===a.id);if(m){s.draft={...normalizeJacc(m),editId:m.id};s.history=[];}route='home';}if(a.type==='play'){const m=s.models.find(m=>m.id===a.id);if(m){s.activeId=m.id;play=true;}}if(a.type==='save'){s.draft=normalizeJacc(s.draft);let m=s.models.find(m=>m.id===s.draft.editId);if(!m&&s.models.length>=8){message='Eight astronauts are saved. Choose one to edit, or keep playing with a saved astronaut.';route='library:0';}else{if(!m){let n=1;while(s.models.some(m=>m.id==='c'+n))n++;m={id:'c'+n};s.models.push(m);}Object.assign(m,JSON.parse(JSON.stringify(s.draft)),{editId:null});s.draft.editId=m.id;s.activeId=m.id;play=true;message='Your J.A.C.C. is saved and ready.';}}return {builder:normalizeJaccBuilder(s),route,message,play};}
