 if(kind==='identity')return v('My astronaut','Choose a name, face and skin tone. Nationality is optional. Every astronaut is a kid, ready to explore.',[go('✏ My name: '+(d.name||'My Astronaut'),'name'),go('🙂 Skin tone','skin'),go('😊 Face','face'),go('🌍 Nationality: '+(d.country||'Your choice'),'country'),home]);
