 if(['options','paint'].includes(kind)&&jaccSlots[arg]){const page=Math.max(0,parseInt(arg2)||0),paint=kind==='paint',options=paint?Object.keys(jaccPaints):jaccSlots[arg].options;return v((paint?'Paint ':'Choose ')+jaccSlots[arg].name,'Any offered choice fits. Your other parts stay as you chose them.',list(options,page,value=>({label:(paint?value[0].toUpperCase()+value.slice(1):jaccJobs[value]?jaccJobs[value].icon+' '+jaccJobs[value].name:jaccNames[value]),type:paint?'paint':'part',slot:arg,value}),go('← This part','slot:'+arg),kind+':'+arg+':'));}
