 if(slot==='boots')a+=`<path d="M32 123h23v29H28v-12h4m33-17h23v17h4v12H65z" fill="${paint}" stroke="${metal}" stroke-width="3"/><path d="M30 147h23m14 0h23" stroke="#17384a" stroke-width="5"/>`+(part==='moon'?`<path d="M32 135h21m14 0h21" stroke="${metal}" stroke-width="6"/>`:part==='wade'?`<path d="M27 152h29m8 0h30" stroke="${energy}" stroke-width="5"/>`:'');
