 if(['left','right'].includes(slot)){const x=slot==='left'?7:91;a+=`<rect x="${x}" y="80" width="22" height="43" rx="8" fill="${paint}" stroke="${metal}" stroke-width="3"/><circle cx="${x+11}" cy="123" r="11" fill="${paint}" stroke="${metal}" stroke-width="3"/>`;if(part!=='none'){const index=Object.keys(jaccJobs).indexOf(part);a+=`<rect x="${x+2}" y="94" width="18" height="17" rx="3" fill="#17384a"/><path d="M${x+6} 100h10m-10 5h${4+(index%3)*3}" stroke="${energy}" stroke-width="3"/>`;a+=`<g transform="translate(${x+11} 102) scale(.65)">${jaccGlyph(part)}</g>`;if(part==='engineering')a+=`<path d="M${x+2} 134l9 11 9-11" fill="${metal}"/>`;}}
