export function jaccSvg(raw){return '<svg xmlns="http://www.w3.org/2000/svg" width="120" height="160" viewBox="0 0 120 160">'+jaccLayerOrder.map(slot=>jaccPartSvg(jaccLayerKey(raw,slot)).replace(/^<svg[^>]*>|<\/svg>$/g,'')).join('')+'</svg>';}
